mapper.select:
SELECT ast01_class_tree_id AS class_tree_id , ast01_item_s_class_nm AS item_s_class_name , ast01_corp_id AS corp_id , ast01_corp_nm AS corp_name , ast01_class_tree_nm AS class_tree_name , ast01_corp_account_nm AS corp_account_name , ast01_corp_pay_account_info AS corp_pay_account_info FROM ( SELECT ast01_class_tree.* , COALESCE(sys15_corp_nm,'') AS ast01_corp_nm , f_get_corp_nm(ast01_corp_id)||'('||ast01_class_tree_nm||')' AS ast01_corp_account_nm , f_cdnm('ItemSClassCode', ast01_item_s_class_cd, ast01_company_id, f_sysdate()) AS ast01_item_s_class_nm , COALESCE(sys09_seq, ast01_item_s_class_cd) AS ast01_item_s_class_seq , ( SELECT CONCAT( f_cdnm('BankCode', sys17_bank_cd, 0, f_today()) , ' '||TO_DECRYPTS(sys17_account_no) , ' '||sys17_account_nm) FROM sys17_corp_account WHERE sys17_corp_id = ast01_corp_id AND sys17_main_account_yn = 'true' LIMIT 1 ) AS ast01_corp_pay_account_info FROM ast01_class_tree LEFT OUTER JOIN sys15_corp ON sys15_corp_id = ast01_corp_id LEFT OUTER JOIN ( SELECT sys09_code.* FROM sys08_code_kind INNER JOIN sys09_code ON ( sys09_code_kind_id = sys08_code_kind_id AND sys09_company_id = 0 ) WHERE sys08_kind_cd = 'ItemSClassCode' AND COALESCE(sys09_close_yn,'false') = 'false' ) sys ON sys09_code = ast01_item_s_class_cd WHERE ast01_company_id = #{companyId} AND ast01_type_cd = 'IT' AND ast01_asset_type = '1' AND ast01_item_s_class_cd IN ( SELECT sys09_code FROM sys13_code_group INNER JOIN sys09_code ON sys09_code_id = sys13_code_id WHERE sys13_kind_group_cd = 'ItemSClassCode003' ) AND COALESCE(ast01_mat_date,'9999-12-31') >= #{stdDate} AND COALESCE(ast01_use_yn, 'false') = 'true'
AND ast01_item_m_class_cd = '9030' /*(9030:선급금)*/
AND ast01_corp_id = #{corpId}
) a WHERE upper(ast01_class_tree_nm||ast01_corp_nm) like '%'||upper(#{searchText})||'%' ORDER BY ast01_item_m_class_cd, ast01_item_s_class_seq, ast01_corp_nm collate "ko_KR.utf8" asc, ast01_seq
